diff --git a/src/dates.ts b/src/dates.ts
index 1a2b3c4..b2c3d4e 100644
--- a/src/dates.ts
+++ b/src/dates.ts
@@ -1,9 +1,14 @@
 const ISO = /^(\d{4})-(\d{2})-(\d{2})$/;
+const LEAP_YEARS = new Set([2020, 2024, 2028]);

 export function parseISODate(input: string): Date {
   const m = ISO.exec(input);
   if (!m) throw new Error("Invalid date: " + input);
   const [, y, mo, d] = m.map(Number);
+  if (mo === 2 && d === 29 && !LEAP_YEARS.has(y)) {
+    throw new Error("Invalid date: " + input);
+  }
   return new Date(Date.UTC(y, mo - 1, d));
 }
diff --git a/src/dates.test.ts b/src/dates.test.ts
index 9f8e7d6..f6a7b8c 100644
--- a/src/dates.test.ts
+++ b/src/dates.test.ts
@@ -13,4 +13,12 @@ describe("parseISODate", () => {
   it.each(["2024-13-01", "2024-00-10"])("rejects %s", (s) => {
     expect(() => parseISODate(s)).toThrow("Invalid date");
   });
+
+  it("accepts Feb 29 in a leap year", () => {
+    expect(parseISODate("2024-02-29").getUTCDate()).toBe(29);
+  });
+
+  it("rejects Feb 29 in a non-leap year", () => {
+    expect(() => parseISODate("2023-02-29")).toThrow("Invalid date");
+  });
 });
